96	export type CommonGroundScoreCancelReason =
97	  | 'new-story'
98	  | 'optional-survey-action'
99	  | 'actor-change'
100	  | 'world-change'
101	  | 'reset'
102	  | 'exit'
103	  | 'pause'
104	  | 'visibility-loss'
105	  | 'music-mute'
106	  | 'audio-unavailable';
