108	interface CommonGroundScoreRuntime {
109	  beat: StoryBeat | null;
110	  mood: CommonGroundMoodId | null;
111	  /** Live-only final texture. Never serialized, never restored. */
112	  finalTexture: { beat: StoryBeat; startedAtMs: number } | null;
113	}
