118	 * MONOTONIC WALL TIME, NOT GAMEPLAY TIME.
119	 *
120	 * The five seconds are five seconds of the player's life, so the deadline may not
121	 * be made of accumulated frame deltas: a clamped `dt`, a stalled frame, a
122	 * background tab or a slow machine would each quietly lengthen a bounded
123	 * exception that is bounded precisely because nobody agreed to more of it.
124	 * `performance.now()` never goes backwards; `Date.now()` is the fallback where it
125	 * does not exist, and a wall-clock adjustment there is handled by the clamp in
126	 * `elapsedSeconds`.
127	 */
128	function monotonicNowMs(): number {
129	  const perf = (globalThis as { performance?: { now?: () => number } }).performance;
130	  return typeof perf?.now === 'function' ? perf.now() : Date.now();
131	}
132	
133	function elapsedSeconds(startedAtMs: number): number {
134	  return Math.max(0, (monotonicNowMs() - startedAtMs) / 1000);
135	}
136	
137	/**
138	 * Publish a mood ONCE PER SEMANTIC VARIANT EDGE.
139	 *
140	 * Re-submitting the same variant is suppressed here rather than in the engine,
141	 * because a per-frame resubmission is what would turn a held texture into a
142	 * stutter and make every sample of a trace sound like an event. Nothing in this
143	 * chapter is scored per sample.
144	 */
145	export function setCommonGroundMood(beat: StoryBeat, mood: CommonGroundMoodId): boolean {
146	  if (runtime.beat === beat && runtime.mood === mood) return false;
147	  runtime.beat = beat;
148	  runtime.mood = mood;
149	  setStoryScoreMoodOverride(beat, CG_MOODS[mood]);
150	  return true;
151	}
152	
153	/**
154	 * Hand the beat back to the world conductor.
155	 *
156	 * ORDER MATTERS AND IS SIGNED: `setScoreBeat(null)` first, THEN the override is
157	 * cleared. Clearing the override while the beat is still selected re-tunes the
158	 * instrument to the chapter's mapped mood for the frame in between, which is
159	 * audible as a short reassertion of exactly the texture that is being released.
160	 *
161	 * Used by the return choice, and by the release of the completion token. Hatch,
162	 * lift and the Origin landing do NOT call this and do not select anything: after
163	 * the return is chosen the world conductor already owns the travel, and
164	 * reselecting `restored-home` over it would put the hearth's music in the sky.
165	 */
166	export function releaseCommonGroundMood(beat: StoryBeat): boolean {
167	  if (runtime.beat !== beat && runtime.mood === null) return false;
168	  setScoreBeat(null);
169	  clearStoryScoreMoodOverride(beat);
170	  runtime.beat = null;
171	  runtime.mood = null;
172	  return true;
173	}
174	
175	export function enterCommonGroundScoreBeat(beat: StoryBeat | null): void {
176	  if (beat === null) {
177	    runtime.beat = null;
178	    runtime.mood = null;
179	    return;
180	  }
181	  if (runtime.beat !== beat) {
182	    runtime.mood = null;
183	    runtime.beat = beat;
184	  }
185	}
186	
187	export interface CommonGroundFinalTextureEligibility {
188	  /** True when the completion was ALREADY true in the loaded save. */
189	  restoredCompletion: boolean;
190	  /** True when the audio output cannot carry it at this exact edge. */
191	  audioUnavailable?: boolean;
192	}
193	
194	/**
195	 * Begin the live-only final texture, at the ACTUAL first completion.
196	 *
197	 * THE TEST IS THE COMPLETION EDGE, NOT THE SNAPSHOT'S PROVENANCE. A save that
198	 * already carried the reciprocal proof has nothing to acknowledge, and a receipt
199	 * read is not an event. But a save loaded halfway through the chapter is also
200	 * "hydrated", and the completion the player then physically earns is a first
201	 * completion in every sense that matters — using the snapshot-wide flag as the
202	 * predicate would ban the texture for every Continue forever.
203	 *
204	 * Audio being unavailable or muted at this edge CANCELS eligibility outright.
205	 * It is not queued for a later unlock: the moment is the moment.
206	 */
207	export function beginCommonGroundFinalTexture(
208	  beat: StoryBeat,
209	  eligibility: CommonGroundFinalTextureEligibility
210	): boolean {
211	  if (eligibility.restoredCompletion || eligibility.audioUnavailable) return false;
212	  if (runtime.finalTexture) return false;
213	  setCommonGroundMood(beat, 'independent-action-settled');
214	  runtime.finalTexture = { beat, startedAtMs: monotonicNowMs() };
215	  return true;
216	}
217	
218	export function commonGroundFinalTextureHolds(): boolean {
219	  return runtime.finalTexture !== null;
220	}
221	
222	/**
223	 * Advance the live token. Returns true on the frame it releases.
224	 *
225	 * The deadline releases PRESENTATION INTENT ONLY. Controls, progression and the
226	 * guidance retirement all happened at the commit; nothing waits on this.
227	 *
228	 * The parameter is retained so every existing caller keeps its shape, but it is
229	 * deliberately UNUSED: the deadline is monotonic elapsed time. This is also why
230	 * the `done` frames after the handback must keep calling it — the chapter beat
231	 * is gone by then, and a token whose only tick lived inside the chapter would
232	 * either hang forever or need a second, competing release path.
233	 */
234	export function tickCommonGroundFinalTexture(_dtSeconds?: number): boolean {
235	  const token = runtime.finalTexture;
236	  if (!token) return false;
237	  if (elapsedSeconds(token.startedAtMs) < COMMON_GROUND_FINAL_TEXTURE_MAX_SECONDS) return false;
238	  releaseCommonGroundFinalTexture();
239	  return true;
240	}
241	
242	/** The normal release: hand back to the existing 4.5-second complementary fade. */
243	function releaseCommonGroundFinalTexture(): void {
244	  const token = runtime.finalTexture;
245	  runtime.finalTexture = null;
246	  if (!token) return;
247	  // Same signed ordering as every other release: deselect, then clear.
248	  setScoreBeat(null);
249	  clearStoryScoreMoodOverride(token.beat);
250	  runtime.beat = null;
251	  runtime.mood = null;
252	}
253	
254	/**
255	 * Cancel immediately on any signed trigger. A cancelled token never resumes,
256	 * never hydrates and never defers to unlock — it is simply gone, and the
257	 * existing click-free release owns the tail.
258	 */
259	export function cancelCommonGroundFinalTexture(_reason: CommonGroundScoreCancelReason): boolean {
260	  if (!runtime.finalTexture) return false;
261	  releaseCommonGroundFinalTexture();
262	  return true;
263	}
264	
265	/** Chapter exit: drop local ownership without touching any other chapter's. */
266	export function releaseCommonGroundScore(beat: StoryBeat | null): void {
267	  cancelCommonGroundFinalTexture('exit');
268	  if (beat) clearStoryScoreMoodOverride(beat);
269	  runtime.beat = null;
270	  runtime.mood = null;
271	}
272	
273	export function resetCommonGroundScoreRuntime(): void {
274	  runtime.beat = null;
275	  runtime.mood = null;
276	  runtime.finalTexture = null;
277	}
278	
279	/** Test/diagnostic read; never a progression authority. */
280	export function getCommonGroundScoreDiagnostic(): {
281	  readonly beat: StoryBeat | null;
282	  readonly mood: CommonGroundMoodId | null;
283	  readonly finalTextureSeconds: number | null;
284	} {
285	  return {
286	    beat: runtime.beat,
287	    mood: runtime.mood,
288	    finalTextureSeconds: runtime.finalTexture ? elapsedSeconds(runtime.finalTexture.startedAtMs) : null
289	  };
290	}
