380	/**
381	 * The world conductor's own frames.
382	 *
383	 * `anc.cg.return-chosen` RELEASES the chapter's score, and the three travel
384	 * anchors after it are no-ops. They keep their signed `restored-home` binding in
385	 * the table above — the cue reference is a fact about the contract — but a cue
386	 * reference has never been an instruction to publish. Reselecting the hearth's
387	 * mood at the hatch, at the lift or on the Origin landing would be this chapter
388	 * scoring somebody else's travel.
389	 */
390	const CG_RELEASING_ANCHOR = 'anc.cg.return-chosen';
391	const CG_WORLD_CONDUCTOR_ANCHORS: ReadonlySet<string> = new Set([
392	  'anc.cg.hatch-boarded',
393	  'anc.cg.lift-committed',
394	  'anc.cg.origin-landed'
395	]);
396	
397	/**
398	 * Publish one signed anchor from its real owner.
399	 *
400	 * `once` is the default because a physical fact happens once. The contingent
401	 * hold/resume anchors pass `once: false` — a reference can genuinely lapse and
402	 * be re-established more than once, and the score's own de-duplication (same
403	 * variant, no republication) is what keeps that from restarting a mood.
404	 */
405	function noteAnchor(anchorId: string, options: { once?: boolean; entry?: boolean } = {}): boolean {
406	  const once = options.once ?? true;
407	  if (once && runtime.firedAnchors.has(anchorId)) return false;
408	  runtime.firedAnchors.add(anchorId);
409	  requestAnchorActivation(anchorId, options.entry === true);
410	  const mood = CG_ANCHOR_MOOD[anchorId];
411	  const beat = runtime.beat;
412	  if (mood && beat) {
413	    if (anchorId === CG_RELEASING_ANCHOR) {
414	      releaseCommonGroundMood(beat);
415	    } else if (CG_WORLD_CONDUCTOR_ANCHORS.has(anchorId) || CG_RETAINING_ANCHORS.has(anchorId)) {
416	      // Deliberately nothing. Whatever is current stays current.
417	      return true;
418	    } else if (anchorId === 'anc.cg.complete') {
419	      // The ONE new behaviour: a live-only texture on a real first completion.
420	      // Eligibility is the COMPLETION EDGE, not the snapshot's provenance: a
421	      // save resumed mid-chapter still earns its first completion live.
422	      beginCommonGroundFinalTexture(beat, {
423	        restoredCompletion: runtime.completionWasRestored,
424	        audioUnavailable: commonGroundAudioUnavailable()
425	      });
426	    } else if (anchorId === 'anc.cg.handback') {
427	      // The handback binds the SAME settled cue. It must not become a second
428	      // door into it: if eligibility was refused a frame ago — restored, muted,
429	      // no output — this anchor cannot quietly publish the mood anyway, and it
430	      // must never restart or re-queue a token that is already running.
431	      if (!commonGroundFinalTextureHolds()) return true;
432	    } else {
433	      setCommonGroundMood(beat, mood);
434	    }
435	  }
436	  return true;
437	}
